import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"58、【兑】 兑下兑上","description":"周易口诀义 - 58、【兑】 兑下兑上","frontmatter":{"title":"58、【兑】 兑下兑上","description":"周易口诀义 - 58、【兑】 兑下兑上"},"headers":[],"relativePath":"zh/classics/koujueyi/060.md","filePath":"zh/classics/koujueyi/060.md"}'),r={name:"zh/classics/koujueyi/060.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_58、【兑】-兑下兑上" tabindex="-1">58、【兑】 兑下兑上 <a class="header-anchor" href="#_58、【兑】-兑下兑上" aria-label="Permalink to “58、【兑】 兑下兑上”">​</a></h1><p>象曰：丽泽，兑。君子以朋友讲习。</p><p>初九：和兑，吉。</p><p>象曰：「和兑」之「吉」，行未疑也。</p><p>九二：孚兑，吉，悔亡。</p><p>象曰：「孚兑」之「吉」，信志也。</p><p>六三：来兑，凶。</p><p>象曰：「来兑」之「凶」，位不当也。</p><p>九四：商兑未宁，介疾有喜。</p><p>象曰：「九四」之「喜」，有庆也。</p><p>九五：孚于剥，有厉。</p><p>象曰：「孚于剥」，位正当也。</p><p>上六：引兑。</p><p>象曰：「上六引兑」，未光也。</p><p>解读</p><p>「兑亨，利贞」者，兑泽能润悦万物，故谓「兑悦」也。喻人君能以兑泽润于万人，惠流人悦，无所不通，故曰「兑亨」也。以悦相亲，恐陷邪谄，其所利者在贞正，故曰「利贞」也。象曰「丽泽，兑」者，丽犹连也；两泽相连，上下俱悦，故曰「丽泽，兑」也。「君子以朋友讲习」者，先儒云：「同处师门曰朋，共执一志曰友。」友犹党也。必须友者，学记云：「独学无友，即孤陋寡闻。」谓朋友聚居，讲解道义，修习文礼，相悦之盛，莫盛于此。故郑众云：「乐耽于酒，则有沉酗之凶；志累于乐，则有伤性之患。所以君子乐之美者，莫过于尚诗、书，敦习道义，教之盛矣，乐在斯焉。」</p><p>「初九，和兑，吉」者，处悦之初，而无私应，与众和悦，天下皆亲，以斯而往，何所疑乎？所以获「吉」也。</p><p>「九二，孚兑，吉，悔亡」者，以刚处中，是怀信实之人，悦而施信，则吉从之，故曰「孚兑，吉」；失位而处，所以有悔；志在忠信，所以「悔亡」也。</p><p>「六三来兑，凶」者，以阴居阳位，是来求悦；以不正之身，妄来求悦，是佞邪之道，所以致凶也。</p><p>「九四，商兑未宁，介□有喜」者，商谓商量裁制之谓；介，隔也。六三以谄佞之身而近至尊，妄求干宠。夫佞邪之人，国之患害。今九四既是权臣，为君委任，固宜与君商量裁制，介隔邪佞之人，内掌枢机，以匡王室，经营伦理，未遑安宁，故曰「商兑未宁」也。介，疾是隔邪。与君除害，四方安静，故有喜庆，故曰「介□有喜」也。</p><p>九五：「孚于剥，有厉」者，剥是小人道长之称也。九五为悦之主，固宜中正自安，惟贤是任，而乃反亲上六，昵狎小人，遂为小人所害，危厉，故曰「孚于剥，有厉」。书曰：「远耆德，比顽童，是为乱风也。」</p><p>上六引兑者，六以阴最居悦后，是自静退，不妄求进，必须他人牵引，乃从众悦，故曰「引兑」也。</p>',22)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
